8: `timescale 1ns/1ps
9: 
10: // ============================================================================
11: // Small signed comb adder (W-bit + W-bit -> (W+1)-bit)
12: // ============================================================================
13: module shared_adder_comb #(
14:   parameter integer W = 8
15: )(
16:   input  wire [W-1:0] a,
17:   input  wire [W-1:0] b,
18:   output wire [W:0]   y
19: );
20:   assign y = {a[W-1], a} + {b[W-1], b};
21: endmodule
22: 
23: // ============================================================================
24: // Block-floating accumulator (unsigned magnitude input, explicit sign)
25: // - GRS precision below the original mantissa LSB
26: // - 1-cycle input capture on in_valid (mul_done)
27: // - Compute/accumulate uses ONLY registered inputs
28: // - acc_valid pulses HIGH for exactly 1 cycle on commit (the cycle after capture)
29: // - Signed exponent alignment uses round-to-nearest-even
30: // ============================================================================
31: module pe_bfp_acc #(
32:   parameter integer IN_EXPW   = 5,   // width of in_exp
33:   parameter integer IN_MANW   = 3,   // logical integer mantissa width
34:   parameter integer MUL_GUARD = 0,   // sub-integer guard bits below in_mag LSB
35:   parameter integer ACC_EXPW  = 4,   // accumulator exponent width (block floating)
36:   parameter integer ACC_MANW  = 3,   // exposed accumulator mantissa width (integer)
37:   parameter integer GRS       = 3    // guard/round/sticky fractional bits below LSB
38: )(
39:   input  wire                              clk,
40:   input  wire                              rst_n,
41:   input  wire                              stall,       // freeze all state on array stall
42:   input  wire                              clear_acc,   // pulse to clear accumulator
43: 
44:   input  wire                              in_valid,    // 1-cycle pulse (mul_done)
45:   input  wire                              in_zero,     // zero-product token; commit without changing state
46:   input  wire                              in_sign,     // 1=negative term
47:   input  wire [IN_EXPW-1:0]                in_exp,      // unbiased exponent
48:   input  wire [IN_MANW+1+MUL_GUARD:0]      in_mag,      // UNSIGNED magnitude: (IN_MANW+2) integer bits + MUL_GUARD sub-integer bits
49: 
50:   output reg                      acc_sign,    // accumulator sign (MSB of widened mantissa)
51:   output reg  [ACC_EXPW-1:0]      acc_exp,     // accumulator block exponent
52:   output reg  [ACC_MANW+GRS-1:0]  acc_man,     // widened magnitude (ACC_MANW int bits + GRS frac)
53:   output reg                      acc_valid    // 1-cycle pulse when a new sum is committed
54: );
55:   // -----------------------------
56:   // One-cycle input capture stage
57:   // -----------------------------
58:   reg                              r_in_zero;
59:   reg                              r_in_sign;
60:   reg [IN_EXPW-1:0]                r_in_exp;
61:   reg [IN_MANW+1+MUL_GUARD:0]      r_in_mag;
62:   reg                              proc_en;   // delayed in_valid (commit enable)
63: 
64:   always @(posedge clk or negedge rst_n) begin
65:     if (!rst_n) begin
66:       r_in_zero <= 1'b0;
67:       r_in_sign <= 1'b0;
68:       r_in_exp  <= {IN_EXPW{1'b0}};
69:       r_in_mag  <= {(IN_MANW+2+MUL_GUARD){1'b0}};
70:       proc_en   <= 1'b0;
71:     end else if (!stall) begin
72:       proc_en <= in_valid;  // arm commit for next cycle
73:       if (in_valid) begin
74:         r_in_zero <= in_zero;
75:         r_in_sign <= in_sign;
76:         r_in_exp  <= in_exp;
77:         r_in_mag  <= in_mag;
78:       end
79:     end
80:   end
81: 
82:   // -----------------------------
83:   // Widened internal state.
84:   //   EXT_W = ACC_MANW + GRS. Widened mantissa is (EXT_W+1)-bit signed 2's comp:
85:   //     [EXT_W]         = sign
86:   //     [EXT_W-1:GRS]   = ACC_MANW integer magnitude bits (matching pre-GRS view)
87:   //     [GRS-1:0]       = guard/round/sticky fractional bits below original LSB
88:   // Numeric value: value = signed(acc_m_ext) * 2^(acc_exp - INTERNAL_BIAS - GRS).
89:   // The +GRS scale is folded into the output decode bias (see bfp_normalize.v).
90:   // -----------------------------
91:   localparam integer WEXT     = ACC_MANW;
92:   localparam integer EXT_W    = ACC_MANW + GRS;
93:   localparam integer INW      = IN_MANW + 2 + MUL_GUARD;
94:   // The product magnitude carries MUL_GUARD sub-integer bits below the
95:   // classical FP8 LSB. Insertion into the accumulator shifts left by
96:   // (GRS - MUL_GUARD) so those sub-integer bits sit at (or below) the
97:   // accumulator's GRS boundary. When MUL_GUARD == GRS the shift is 0.
98:   localparam integer INS_GRS  = GRS - MUL_GUARD;
99: 
100:   reg  signed [EXT_W:0] acc_m_ext;
101:   reg                   acc_zero;
102: 
103:   // Widen input term to (EXT_W+1) bits, then left-shift by INS_GRS. The
104:   // arithmetic shift-form avoids a zero-width replicate `{0{1'b0}}` when
105:   // MUL_GUARD == GRS (INS_GRS == 0), which some tools mis-handle.
106:   wire signed [EXT_W:0] in_mag_wide =
107:       $signed({{(EXT_W+1-INW){1'b0}}, r_in_mag}) <<< INS_GRS;
108:   wire signed [EXT_W:0] in_term_signed = r_in_sign ? -in_mag_wide : in_mag_wide;
109: 
110:   // Exponent difference acc - in (signed)
111:   wire signed [ACC_EXPW:0] acc_exp_ext = $signed({1'b0, acc_exp});
112:   wire signed [ACC_EXPW:0] in_exp_ext  = $signed({{(ACC_EXPW-IN_EXPW+1){1'b0}}, r_in_exp});
113:   wire signed [ACC_EXPW:0] exp_diff_ai = acc_exp_ext - in_exp_ext; // + => acc>=in
114:   wire [ACC_EXPW-1:0] in_exp_resized = ACC_EXPW'(r_in_exp);
115: 
116:   // Signed right shift with round-to-nearest-even on magnitude. Treating the
117:   // sticky bit as a numeric LSB made every tiny negative term contribute -1
118:   // accumulator unit after a large exponent cancellation. RNE is symmetric:
119:   // sub-half-ULP terms disappear and ties round to an even retained LSB.
120:   function signed [EXT_W:0] arith_shr_rne;
121:     input signed [EXT_W:0] val;
122:     input integer          sh;
123:     integer i;
124:     reg                    val_sign;
125:     reg [EXT_W:0]          magnitude;
126:     reg [EXT_W:0]          quotient;
127:     reg                    guard;
128:     reg                    sticky;
129:     begin
130:       if (sh <= 0) begin
131:         arith_shr_rne = val;
132:       end else begin
133:         val_sign = val[EXT_W];
134:         magnitude = val_sign ? (~val + 1'b1) : val;
135:         quotient = (sh > (EXT_W+1)) ? {(EXT_W+1){1'b0}}
136:                                      : (magnitude >> sh);
137:         guard = 1'b0;
138:         sticky = 1'b0;
139:         for (i = 0; i <= EXT_W; i = i + 1) begin
140:           if (i == (sh-1))
141:             guard = magnitude[i];
142:           else if (i < (sh-1))
143:             sticky = sticky | magnitude[i];
144:         end
145:         if (guard && (sticky || quotient[0]))
146:           quotient = quotient + 1'b1;
147:         arith_shr_rne = val_sign ? -$signed(quotient)
148:                                  :  $signed(quotient);
149:       end
150:     end
151:   endfunction
152: 
153:   // Align to larger exponent
154:   reg  [ACC_EXPW-1:0]   work_exp;
155:   reg  signed [EXT_W:0] acc_aligned, in_aligned;
156: 
157:   always @* begin
158:     if (acc_zero) begin
159:       work_exp    = in_exp_resized;
160:       acc_aligned = { (EXT_W+1){1'b0} };
161:       in_aligned  = in_term_signed;
162:     end else if (exp_diff_ai >= 0) begin
163:       // acc's exp >= in's: shift in down (into GRS bits, precision preserved)
164:       work_exp    = acc_exp;
165:       acc_aligned = acc_m_ext;
166:       in_aligned  = arith_shr_rne(in_term_signed, exp_diff_ai);
167:     end else begin
168:       // in's exp > acc's: shift acc down
169:       work_exp    = in_exp_resized;
170:       acc_aligned = arith_shr_rne(acc_m_ext, -exp_diff_ai);
171:       in_aligned  = in_term_signed;
172:     end
173:   end
174: 
175:   // Add with 1 sign-extension bit, then 1-bit signed RNE renormalize on
176:   // overflow. With a one-bit shift the dropped bit is an exact half-way bit;
177:   // increment only when the retained magnitude is odd (ties to even).
178:   wire signed [EXT_W+1:0] sum_ext =
179:       $signed({acc_aligned[EXT_W], acc_aligned}) +
180:       $signed({in_aligned [EXT_W], in_aligned });

359:   // bits let progressive right shifts by 4 or 5 produce nonzero contributions
360:   // that a 4-bit significand would truncate to zero.
361:   localparam integer MUL_MAG_W = ACT_MBITS + 1 + MUL_GUARD;
362:   // Local shared adder (mantissa work)
363:   reg  signed [ADDW-1:0] add_a, add_b;
364:   wire signed [ADDW:0]   add_y;
365:   reg  signed [ADDW:0]   add_y_q;
366: 
367:   reg [MUL_MAG_W-1:0]    shifted_act;    // implicit 1 prefixed, widened by MUL_GUARD
368:   reg [DATA_WIDTH-1:0]   shifted_man;    // running weight mantissa shift
369: 
370:   wire [ACT_EBITS-1:0] act_exp_field =
371:       act[ACT_EBITS+ACT_MBITS-1 : ACT_MBITS];
372:   wire [ACT_MBITS-1:0] act_man_field = act[ACT_MBITS-1:0];
373:   wire act_exp_zero = (act_exp_field == {ACT_EBITS{1'b0}});
374:   wire act_exp_reserved = &act_exp_field;
375:   wire act_is_zero = act_exp_zero && (act_man_field == {ACT_MBITS{1'b0}});
376: 
377:   // FP8 policy used by the reference model:
378:   //   exp=0, man=0 : zero
379:   //   exp=0, man!=0: subnormal (effective exponent=1, no hidden bit)
380:   //   exp=all-ones : saturate to max finite (exp=all-ones-1, man=all-ones)
381:   wire [ACT_EBITS-1:0] act_exp_effective =
382:       act_exp_reserved ? ({ACT_EBITS{1'b1}} - 1'b1) :
383:       act_exp_zero     ? {{(ACT_EBITS-1){1'b0}}, 1'b1} :
384:                          act_exp_field;
385:   // Widened significand: the classical (ACT_MBITS+1) integer bits followed by
386:   // MUL_GUARD zero low bits. For the reserved (max-finite) case, saturation
387:   // keeps the top (ACT_MBITS+1) bits at all-ones and pads the guard bits with
388:   // zero so the numeric value is (2^(ACT_MBITS+1)-1) << 0 in the widened
389:   // representation, i.e. still 15 in classical FP8 units.
390:   wire [MUL_MAG_W-1:0] act_temp =
391:       act_exp_reserved ? { {(ACT_MBITS+1){1'b1}}, {MUL_GUARD{1'b0}} } :
392:                          { ~act_exp_zero, act_man_field, {MUL_GUARD{1'b0}} };
393:   localparam [ADDW-1:0] POSIT_EXP_BIAS_W = POSIT_EXP_BIAS[ADDW-1:0];
394: 
395:   shared_adder_comb #(.W(ADDW)) U_ADD (
396:     .a(add_a[ADDW-1:0]),
397:     .b(add_b[ADDW-1:0]),
398:     .y(add_y)
399:   );
400: 
401:   // Combinational adder inputs (depend on cycle phase)
402:   always @* begin
403:     if (cycle0) begin
404:       add_a = {ADDW{1'b0}};
405:       add_b = {ADDW{1'b0}};
406:     end else if (cycle1) begin
407:       // Exponent sum path. A fixed internal posit bias keeps every P=4,
408:       // es<=2 product exponent non-negative without changing its value.
409:       add_a = {{(ADDW-ACT_EBITS){1'b0}}, act_exp_effective}
410:               + POSIT_EXP_BIAS_W;
411:       add_b = {{(ADDW - DATA_WIDTH){data_in[DATA_WIDTH-1]}}, data_in};
412:     end else if (cycle2) begin
413:       // mantissa path: first bit uses current LSB of data_in
414:       add_a = {{(ADDW-MUL_MAG_W){1'b0}}, act_temp};
415:       add_b = data_in[DATA_WIDTH-1] ? {{(ADDW-MUL_MAG_W){1'b0}}, shifted_act}
416:                                     : {ADDW{1'b0}};
417:     end else begin
418:       // later mantissa bits use shifted_man MSB
419:       add_a = add_y_q[ADDW-1:0]; // accumulate running sum
420:       add_b = shifted_man[DATA_WIDTH-1] ? {{(ADDW-MUL_MAG_W){1'b0}}, shifted_act}
421:                                         : {ADDW{1'b0}};
422:     end
423:   end
424: 
425:   // act delivery-window tracker. `act_valid` from the FIFO is a
426:   // one-cycle pulse (registered from stored_read), which does not align
427:   // in general with pe_cycLast (FIFO's precision_count and cycle_gen's
428:   // cnt run on independent phases). Track "did a delivery happen in the
429:   // interval (prev_cycleLast, current_cycleLast]" as a set-hold flag,
430:   // reset on cycleLast with the current-cycle input value so that a
431:   // delivery landing exactly at cycleLast counts for the next window.
432:   reg act_seen;
433:   always @(posedge clk or negedge rst_n) begin
434:     if (!rst_n)
435:       act_seen <= 1'b0;
436:     else if (!stall) begin
437:       if (cycleLast)
438:         act_seen <= act_valid;
439:       else if (act_valid)
440:         act_seen <= 1'b1;
441:     end
442:   end
443:   wire effective_act_valid = act_valid | act_seen;
444: 
445:   // mul_done pulse on final beat (combinational). Both operands must be
446:   // architecturally valid at cycleLast — weight-side via `valid` (from
447:   // decoder), activation-side via `effective_act_valid` (any delivery
448:   // in the current cycleLast window).
449:   wire mul_done_temp = valid & effective_act_valid & cycleLast;
450: 
451:   // Registers for product fields — (valid | _valid) gating
452:   always @(posedge clk or negedge rst_n) begin
453:     if (!rst_n) begin
454:       out_exp_sum_r <= {EXP_SUM_WIDTH{1'b0}};
455:       out_val_r     <= {(ACT_MBITS+2+MUL_GUARD){1'b0}};
456:       out_sign      <= 1'b0;
457:       add_y_q       <= { (ADDW+1){1'b0} };
458:       shifted_act   <= { MUL_MAG_W{1'b0} };
459:       shifted_man   <= { DATA_WIDTH{1'b0} };
460:       mul_done      <= 1'b0;
461:       out_zero      <= 1'b0;
462:     end else if (!stall && (valid | pipe_valid)) begin
463:       mul_done <= mul_done_temp;
464:       if (valid) begin
465:         add_y_q <= add_y;
466:         if (cycle0) begin
467:           out_sign    <= act[ACT_EBITS+ACT_MBITS] ^ data_in[0]; // sign XOR
468:           shifted_act <= act_temp;
469:         end else if (cycle1) begin
470:           out_exp_sum_r <= add_y[EXP_SUM_WIDTH-1:0];
471:           shifted_act   <= shifted_act >>> 1;
472:         end else if (cycle2) begin
473:           shifted_act <= shifted_act >>> 1;
474:           shifted_man <= data_in << 1;
475:           out_val_r   <= add_y[ACT_MBITS+1+MUL_GUARD:0];
476:         end else begin
477:           // Continue shifting the fraction captured on cycle2. Reloading from
478:           // data_in here happened to work for Posit4/5, but filler beats then
479:           // erased the third and later fraction bits at P>=6.
480:           shifted_man <= shifted_man << 1;
481:           shifted_act <= shifted_act >>> 1;
482:           out_val_r   <= add_y[ACT_MBITS+1+MUL_GUARD:0];
483:           if (cycleLast) begin
484:             // The decoder emits its explicit zero flag as the final beat.
485:             out_zero <= data_in[0] | act_is_zero;
486:           end
487:         end
488:       end
489:     end
490:   end
491: endmodule
