497: module fp8_pe_mac_stream #(
498:   parameter integer ACT_EBITS      = 4,
499:   parameter integer ACT_MBITS      = 3,    // fp8 mantissa width
500:   parameter integer EXP_SUM_WIDTH  = 6,    // exponent sum width produced at cycle1
501:   parameter integer DATA_WIDTH     = 6,    // decoded Posit field width
502:   parameter integer ADDW           = 10,   // exponent/shift-add adder width; must cover widened mantissa sum
503:   parameter integer POSIT_EXP_BIAS = 24,
504:   // Accumulator view/precision
505:   parameter integer ACC_EXPW       = 7,
506:   parameter integer ACC_MANW       = 12,   // integer bits of accumulator mantissa
507:   parameter integer GRS            = 3,    // guard/round/sticky bits below LSB
508:   parameter integer MUL_GUARD      = GRS   // sub-integer guard bits; must satisfy MUL_GUARD <= GRS
509: )(
510:     input  wire                                 clk,
511:     input  wire                                 rst_n,
512:     input  wire                                 stall,           // freeze all state on array stall
513:     input  wire                                 acc_clear,       // pulse to clear accumulator before a new dot product
514: 
515:     // pipeline handshakes
516:     input  wire                                 valid,
517:     input  wire                                 cycle0,
518:     input  wire                                 cycle1,
519:     input  wire                                 cycle2,
520:     input  wire                                 cycleLast,

400:     // ship-out FSM (and controller S_WAIT_COMPUTE) were written against.
401:     reg all_rows_done_prev;
402:     always @(posedge clk or negedge rst) begin
403:         if (!rst)
404:             all_rows_done_prev <= 1'b0;
405:         else
406:             all_rows_done_prev <= all_rows_done;
407:     end
408:     wire compute_done = all_rows_done & ~all_rows_done_prev;
409:     assign compute_done_out = compute_done;
410: 
411:     // ------------------------------------------------------------------
412:     // Ship-out FSM + drain pipeline
413:     //   SH_IDLE       : waiting for compute_done
414:     //   SH_SHIP       : hand rows to the stage register (one per accepted cycle)
415:     //   SH_DONE       : wait for stage to drain, then pulse `done` and return
416:     //
417:     // FSM drives internal (emit_valid, emit_row) which select acc_{sign,exp,
418:     // man}_arr[emit_row][*]. Each column is normalized+rescaled combinationally
419:     // and captured into a one-entry stage register. The FP16 conversion runs
420:     // from the stage register (post-pipeline), so the critical path is split
421:     // into (mux -> normalize -> rescale) and (fp16 convert -> port). Adds one
422:     // cycle of drain fill latency; steady-state throughput is unchanged.
423:     // ------------------------------------------------------------------
424:     localparam integer LGN_SAFE = (N > 1) ? $clog2(N) : 1;
425:     localparam [1:0] SH_IDLE = 2'd0, SH_SHIP = 2'd1, SH_DONE = 2'd2;
426:     reg [1:0]          sh_state;
427:     reg                done_r;
428:     reg                compute_done_seen;
429:     reg                emit_valid;
430:     reg [LGN_SAFE-1:0] emit_row;
431:     assign             done = done_r;
432: 
433:     // Stage register (between rescale and FP16 convert). One-entry with a
434:     // valid/ready handshake; accepts new data whenever empty or the current
435:     // entry was accepted by the consumer.
436:     reg                 drain_stage_valid;
437:     reg [LGN_SAFE-1:0]  drain_stage_row;
438:     reg                 drain_stage_sign [0:N-1];
439:     reg [NORM_EXPW-1:0] drain_stage_exp  [0:N-1];
440:     reg [NORM_MANW-1:0] drain_stage_man  [0:N-1];
441: 
442:     wire drain_stage_ready = !drain_stage_valid || out_ready;
443: 
444:     // Combinational drain (per-column) at module scope so the stage register
445:     // can capture all N tuples together.
446:     wire                 drain_scaled_sign [0:N-1];
447:     wire [NORM_EXPW-1:0] drain_scaled_exp  [0:N-1];
448:     wire [NORM_MANW-1:0] drain_scaled_man  [0:N-1];
449: 
450:     always @(posedge clk or negedge rst) begin
451:         if (!rst) begin
452:             sh_state          <= SH_IDLE;
453:             emit_valid        <= 1'b0;
454:             emit_row          <= {LGN_SAFE{1'b0}};
455:             done_r            <= 1'b0;
456:             compute_done_seen <= 1'b0;
457:         end else begin
458:             done_r     <= 1'b0;
459:             emit_valid <= 1'b0;
460:             case (sh_state)
461:                 SH_IDLE: begin
462:                     if (compute_done) compute_done_seen <= 1'b1;
463:                     if (compute_done | compute_done_seen) begin
464:                         sh_state          <= SH_SHIP;
465:                         emit_row          <= {LGN_SAFE{1'b0}};
466:                         emit_valid        <= 1'b1;
467:                         compute_done_seen <= 1'b0;
468:                     end
469:                 end
470:                 SH_SHIP: begin
471:                     emit_valid <= 1'b1;
472:                     if (drain_stage_ready) begin
473:                         if (emit_row == (N-1)) begin
474:                             emit_valid <= 1'b0;
475:                             sh_state   <= SH_DONE;
476:                         end else begin
477:                             emit_row <= emit_row + 1'b1;
478:                         end
479:                     end
480:                 end
481:                 SH_DONE: begin
482:                     emit_valid <= 1'b0;
483:                     if (!drain_stage_valid) begin
484:                         done_r   <= 1'b1;
485:                         sh_state <= SH_IDLE;
486:                     end
487:                 end
488:                 default: sh_state <= SH_IDLE;
489:             endcase
490:         end
491:     end
492: 
493:     integer drc;
494:     always @(posedge clk or negedge rst) begin
495:         if (!rst) begin
496:             drain_stage_valid <= 1'b0;
497:             drain_stage_row   <= {LGN_SAFE{1'b0}};
498:             for (drc = 0; drc < N; drc = drc + 1) begin
499:                 drain_stage_sign[drc] <= 1'b0;
500:                 drain_stage_exp[drc]  <= {NORM_EXPW{1'b0}};
501:                 drain_stage_man[drc]  <= {NORM_MANW{1'b0}};
502:             end
503:         end else if (drain_stage_ready) begin
504:             drain_stage_valid <= emit_valid;
505:             drain_stage_row   <= emit_row;
506:             for (drc = 0; drc < N; drc = drc + 1) begin
507:                 drain_stage_sign[drc] <= drain_scaled_sign[drc];
508:                 drain_stage_exp[drc]  <= drain_scaled_exp[drc];
509:                 drain_stage_man[drc]  <= drain_scaled_man[drc];
510:             end
511:         end
512:     end
